-- Additive LMS learning history. Default-off rollout is controlled by application flags.
CREATE TABLE IF NOT EXISTS lms_staff_permissions (user_id integer NOT NULL REFERENCES users(id) ON DELETE RESTRICT, permission text NOT NULL, PRIMARY KEY(user_id, permission));
CREATE TABLE IF NOT EXISTS lms_course_versions (id bigserial PRIMARY KEY, course_id integer NOT NULL REFERENCES academy_courses(id) ON DELETE RESTRICT, version integer NOT NULL CHECK(version>0), state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','published','archived')), program jsonb NOT NULL DEFAULT '[]', created_by integer REFERENCES users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(course_id,version));
CREATE TABLE IF NOT EXISTS lms_sections (id bigserial PRIMARY KEY, course_version_id bigint NOT NULL REFERENCES lms_course_versions(id) ON DELETE RESTRICT, title text NOT NULL, position integer NOT NULL CHECK(position>=0), UNIQUE(course_version_id,position));
CREATE TABLE IF NOT EXISTS lms_units (id bigserial PRIMARY KEY, course_version_id bigint NOT NULL REFERENCES lms_course_versions(id) ON DELETE RESTRICT, section_id bigint REFERENCES lms_sections(id) ON DELETE RESTRICT, title text NOT NULL, position integer NOT NULL CHECK(position>=0), required boolean NOT NULL DEFAULT true, UNIQUE(course_version_id,position));
CREATE TABLE IF NOT EXISTS lms_group_runs (id bigserial PRIMARY KEY, group_id integer NOT NULL REFERENCES academy_groups(id) ON DELETE RESTRICT, course_version_id bigint NOT NULL REFERENCES lms_course_versions(id) ON DELETE RESTRICT, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','completed','archived')), format text NOT NULL DEFAULT 'offline' CHECK(format IN ('offline','online')), meeting_url text CHECK(meeting_url IS NULL OR meeting_url ~ '^https://'), access_until timestamptz, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(group_id));
CREATE TABLE IF NOT EXISTS lms_lesson_bindings (id bigserial PRIMARY KEY, run_id bigint NOT NULL REFERENCES lms_group_runs(id) ON DELETE RESTRICT, unit_id bigint REFERENCES lms_units(id) ON DELETE RESTRICT, lesson_id integer NOT NULL REFERENCES academy_lessons(id) ON DELETE RESTRICT, format text CHECK(format IN ('offline','online')), meeting_url text CHECK(meeting_url IS NULL OR meeting_url ~ '^https://'), UNIQUE(run_id,lesson_id));
CREATE TABLE IF NOT EXISTS lms_materials (id bigserial PRIMARY KEY, run_id bigint NOT NULL REFERENCES lms_group_runs(id) ON DELETE RESTRICT, unit_id bigint REFERENCES lms_units(id) ON DELETE RESTRICT, state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','published','archived')), created_by integer NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS lms_material_versions (id bigserial PRIMARY KEY, material_id bigint NOT NULL REFERENCES lms_materials(id) ON DELETE RESTRICT, version integer NOT NULL CHECK(version>0), title text NOT NULL, body text NOT NULL, category text NOT NULL CHECK(category IN ('lesson','practice','repeat')), links jsonb NOT NULL DEFAULT '[]', file_ids jsonb NOT NULL DEFAULT '[]', created_by integer NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(material_id,version));
CREATE TABLE IF NOT EXISTS lms_material_publications (id bigserial PRIMARY KEY, material_id bigint NOT NULL REFERENCES lms_materials(id) ON DELETE RESTRICT, material_version_id bigint NOT NULL REFERENCES lms_material_versions(id) ON DELETE RESTRICT, enrollment_id integer NOT NULL REFERENCES academy_student_group_enrollments(id) ON DELETE RESTRICT, publish_at timestamptz NOT NULL, revoked_at timestamptz, UNIQUE(material_version_id,enrollment_id));
CREATE TABLE IF NOT EXISTS lms_material_reads (publication_id bigint NOT NULL REFERENCES lms_material_publications(id) ON DELETE RESTRICT, student_id integer NOT NULL REFERENCES academy_students(id) ON DELETE RESTRICT, read_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(publication_id,student_id));
CREATE TABLE IF NOT EXISTS lms_assignments (id bigserial PRIMARY KEY, run_id bigint NOT NULL REFERENCES lms_group_runs(id) ON DELETE RESTRICT, unit_id bigint REFERENCES lms_units(id) ON DELETE RESTRICT, state text NOT NULL DEFAULT 'published' CHECK(state IN ('draft','published','archived')), created_by integer NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS lms_assignment_versions (id bigserial PRIMARY KEY, assignment_id bigint NOT NULL REFERENCES lms_assignments(id) ON DELETE RESTRICT, version integer NOT NULL CHECK(version>0), title text NOT NULL, body text NOT NULL, required boolean NOT NULL, allowed_answers jsonb NOT NULL, file_ids jsonb NOT NULL DEFAULT '[]', criteria jsonb NOT NULL DEFAULT '[]', grading_mode text NOT NULL CHECK(grading_mode IN ('acceptance','points')), max_score numeric CHECK(max_score>0), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(assignment_id,version), CHECK(grading_mode<>'points' OR max_score IS NOT NULL));
CREATE TABLE IF NOT EXISTS lms_assignment_recipients (id bigserial PRIMARY KEY, assignment_id bigint NOT NULL REFERENCES lms_assignments(id) ON DELETE RESTRICT, assignment_version_id bigint NOT NULL REFERENCES lms_assignment_versions(id) ON DELETE RESTRICT, enrollment_id integer NOT NULL REFERENCES academy_student_group_enrollments(id) ON DELETE RESTRICT, student_id integer NOT NULL REFERENCES academy_students(id) ON DELETE RESTRICT, status text NOT NULL DEFAULT 'assigned' CHECK(status IN ('assigned','submitted','revision_required','accepted','excused','cancelled')), opens_at timestamptz NOT NULL, due_at timestamptz, closes_at timestamptz, version integer NOT NULL DEFAULT 1 CHECK(version>0), reason text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(assignment_id,enrollment_id), CHECK(due_at IS NULL OR due_at>=opens_at), CHECK(closes_at IS NULL OR closes_at>=opens_at));
CREATE TABLE IF NOT EXISTS lms_submission_drafts (recipient_id bigint PRIMARY KEY REFERENCES lms_assignment_recipients(id) ON DELETE RESTRICT, version integer NOT NULL DEFAULT 1 CHECK(version>0), text text NOT NULL DEFAULT '', links jsonb NOT NULL DEFAULT '[]', file_ids jsonb NOT NULL DEFAULT '[]', saved_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS lms_submissions (id bigserial PRIMARY KEY, recipient_id bigint NOT NULL REFERENCES lms_assignment_recipients(id) ON DELETE RESTRICT, assignment_version_id bigint NOT NULL REFERENCES lms_assignment_versions(id) ON DELETE RESTRICT, account_id bigint NOT NULL REFERENCES portal_accounts(id) ON DELETE RESTRICT, attempt_number integer NOT NULL CHECK(attempt_number>0), text text NOT NULL, links jsonb NOT NULL, file_ids jsonb NOT NULL, idempotency_key text NOT NULL, submitted_at timestamptz NOT NULL DEFAULT now(), late boolean NOT NULL, withdrawn_at timestamptz, review_started_by integer REFERENCES users(id) ON DELETE RESTRICT, review_started_at timestamptz, UNIQUE(recipient_id,attempt_number), UNIQUE(account_id,recipient_id,idempotency_key));
CREATE TABLE IF NOT EXISTS lms_reviews (id bigserial PRIMARY KEY, submission_id bigint NOT NULL REFERENCES lms_submissions(id) ON DELETE RESTRICT, decision text NOT NULL CHECK(decision IN ('accepted','revision_required')), comment text NOT NULL DEFAULT '', score numeric CHECK(score>=0), criterion_scores jsonb NOT NULL DEFAULT '{}', reviewer_id integer NOT NULL REFERENCES users(id) ON DELETE RESTRICT, reason text, created_at timestamptz NOT NULL DEFAULT now(), CHECK(decision<>'revision_required' OR length(trim(comment))>0));
CREATE TABLE IF NOT EXISTS lms_quizzes (id bigserial PRIMARY KEY, run_id bigint NOT NULL REFERENCES lms_group_runs(id) ON DELETE RESTRICT, unit_id bigint REFERENCES lms_units(id) ON DELETE RESTRICT, state text NOT NULL DEFAULT 'published' CHECK(state IN ('draft','published','archived')), created_by integer NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS lms_quiz_versions (id bigserial PRIMARY KEY, quiz_id bigint NOT NULL REFERENCES lms_quizzes(id) ON DELETE RESTRICT, version integer NOT NULL CHECK(version>0), title text NOT NULL, instructions text NOT NULL DEFAULT '', required boolean NOT NULL, questions jsonb NOT NULL CHECK(jsonb_array_length(questions)>0), pass_percent numeric NOT NULL CHECK(pass_percent BETWEEN 0 AND 100), max_attempts integer NOT NULL CHECK(max_attempts>0), timer_seconds integer CHECK(timer_seconds>=30), disclosure text NOT NULL CHECK(disclosure IN ('practice','closed','exhausted')), shuffle_questions boolean NOT NULL DEFAULT false, shuffle_options boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(quiz_id,version));
CREATE TABLE IF NOT EXISTS lms_quiz_recipients (id bigserial PRIMARY KEY, quiz_id bigint NOT NULL REFERENCES lms_quizzes(id) ON DELETE RESTRICT, quiz_version_id bigint NOT NULL REFERENCES lms_quiz_versions(id) ON DELETE RESTRICT, enrollment_id integer NOT NULL REFERENCES academy_student_group_enrollments(id) ON DELETE RESTRICT, student_id integer NOT NULL REFERENCES academy_students(id) ON DELETE RESTRICT, opens_at timestamptz NOT NULL, closes_at timestamptz, extra_attempts integer NOT NULL DEFAULT 0 CHECK(extra_attempts>=0), status text NOT NULL DEFAULT 'assigned' CHECK(status IN ('assigned','excused','cancelled')), UNIQUE(quiz_id,enrollment_id), CHECK(closes_at IS NULL OR closes_at>opens_at));
CREATE TABLE IF NOT EXISTS lms_quiz_attempts (id bigserial PRIMARY KEY, recipient_id bigint NOT NULL REFERENCES lms_quiz_recipients(id) ON DELETE RESTRICT, quiz_version_id bigint NOT NULL REFERENCES lms_quiz_versions(id) ON DELETE RESTRICT, account_id bigint NOT NULL REFERENCES portal_accounts(id) ON DELETE RESTRICT, attempt_number integer NOT NULL CHECK(attempt_number>0), version integer NOT NULL DEFAULT 1 CHECK(version>0), state text NOT NULL DEFAULT 'active' CHECK(state IN ('active','finished')), questions jsonb NOT NULL, answers jsonb NOT NULL DEFAULT '{}', started_at timestamptz NOT NULL DEFAULT now(), deadline_at timestamptz, finished_at timestamptz, score numeric, total_score numeric, percent numeric, passed boolean, UNIQUE(recipient_id,attempt_number));
CREATE UNIQUE INDEX IF NOT EXISTS lms_quiz_one_active ON lms_quiz_attempts(recipient_id) WHERE state='active';
CREATE TABLE IF NOT EXISTS lms_learning_events (id bigserial PRIMARY KEY, student_id integer NOT NULL REFERENCES academy_students(id) ON DELETE RESTRICT, run_id bigint NOT NULL REFERENCES lms_group_runs(id) ON DELETE RESTRICT, type text NOT NULL, object_id bigint, event_key text NOT NULL UNIQUE, data jsonb NOT NULL DEFAULT '{}', occurred_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS lms_makeup_plans (id bigserial PRIMARY KEY, lesson_id integer NOT NULL REFERENCES academy_lessons(id) ON DELETE RESTRICT, student_id integer NOT NULL REFERENCES academy_students(id) ON DELETE RESTRICT, run_id bigint NOT NULL REFERENCES lms_group_runs(id) ON DELETE RESTRICT, recipient_id bigint REFERENCES lms_assignment_recipients(id) ON DELETE RESTRICT, quiz_recipient_id bigint REFERENCES lms_quiz_recipients(id) ON DELETE RESTRICT, status text NOT NULL DEFAULT 'needed' CHECK(status IN ('needed','in_progress','completed','not_required')), due_at timestamptz, completed_at timestamptz, completed_by integer REFERENCES users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(lesson_id,student_id));
CREATE TABLE IF NOT EXISTS lms_achievements (id bigserial PRIMARY KEY, student_id integer NOT NULL REFERENCES academy_students(id) ON DELETE RESTRICT, run_id bigint NOT NULL REFERENCES lms_group_runs(id) ON DELETE RESTRICT, rule text NOT NULL, event_key text NOT NULL UNIQUE, title text NOT NULL, reason text NOT NULL, awarded_by integer REFERENCES users(id) ON DELETE RESTRICT, awarded_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz, revoked_by integer REFERENCES users(id) ON DELETE RESTRICT, revoke_reason text, UNIQUE(student_id,run_id,rule));
CREATE TABLE IF NOT EXISTS lms_reports (id bigserial PRIMARY KEY, student_id integer NOT NULL REFERENCES academy_students(id) ON DELETE RESTRICT, run_id bigint NOT NULL REFERENCES lms_group_runs(id) ON DELETE RESTRICT, period_from timestamptz NOT NULL, period_to timestamptz NOT NULL, version integer NOT NULL CHECK(version>0), metrics jsonb NOT NULL, comment text NOT NULL, next_steps text NOT NULL, published_by integer NOT NULL REFERENCES users(id) ON DELETE RESTRICT, published_at timestamptz NOT NULL DEFAULT now(), CHECK(period_to>period_from), UNIQUE(student_id,run_id,period_from,period_to,version));
CREATE TABLE IF NOT EXISTS lms_threads (id bigserial PRIMARY KEY, student_id integer NOT NULL REFERENCES academy_students(id) ON DELETE RESTRICT, run_id bigint NOT NULL REFERENCES lms_group_runs(id) ON DELETE RESTRICT, unit_id bigint REFERENCES lms_units(id) ON DELETE RESTRICT, recipient_id bigint REFERENCES lms_assignment_recipients(id) ON DELETE RESTRICT, title text NOT NULL, audience text NOT NULL CHECK(audience IN ('student_teacher','representative_teacher')), author_account_id bigint NOT NULL REFERENCES portal_accounts(id) ON DELETE RESTRICT, assigned_user_id integer REFERENCES users(id) ON DELETE RESTRICT, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','answered','resolved')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS lms_comments (id bigserial PRIMARY KEY, student_id integer NOT NULL REFERENCES academy_students(id) ON DELETE RESTRICT, run_id bigint NOT NULL REFERENCES lms_group_runs(id) ON DELETE RESTRICT, recipient_id bigint REFERENCES lms_assignment_recipients(id) ON DELETE RESTRICT, thread_id bigint REFERENCES lms_threads(id) ON DELETE RESTRICT, account_id bigint REFERENCES portal_accounts(id) ON DELETE RESTRICT, staff_user_id integer REFERENCES users(id) ON DELETE RESTRICT, audience text NOT NULL CHECK(audience IN ('student_teacher','family_teacher','staff','representative_teacher')), body text NOT NULL, file_ids jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), CHECK((account_id IS NULL)<>(staff_user_id IS NULL)), CHECK((recipient_id IS NULL)<>(thread_id IS NULL)));
CREATE TABLE IF NOT EXISTS lms_comment_reads (comment_id bigint NOT NULL REFERENCES lms_comments(id) ON DELETE RESTRICT, account_id bigint NOT NULL REFERENCES portal_accounts(id) ON DELETE RESTRICT, read_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(comment_id,account_id));
CREATE TABLE IF NOT EXISTS lms_announcements (id bigserial PRIMARY KEY, run_id bigint NOT NULL REFERENCES lms_group_runs(id) ON DELETE RESTRICT, title text NOT NULL, body text NOT NULL, audience text NOT NULL CHECK(audience IN ('students','representatives','all')), file_ids jsonb NOT NULL DEFAULT '[]', publish_at timestamptz NOT NULL, pinned_until timestamptz, revoked_at timestamptz, created_by integer NOT NULL REFERENCES users(id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS lms_announcement_reads (announcement_id bigint NOT NULL REFERENCES lms_announcements(id) ON DELETE RESTRICT, account_id bigint NOT NULL REFERENCES portal_accounts(id) ON DELETE RESTRICT, read_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(announcement_id,account_id));
CREATE TABLE IF NOT EXISTS lms_course_completions (id bigserial PRIMARY KEY, student_id integer NOT NULL REFERENCES academy_students(id) ON DELETE RESTRICT, run_id bigint NOT NULL REFERENCES lms_group_runs(id) ON DELETE RESTRICT, completed_by integer NOT NULL REFERENCES users(id) ON DELETE RESTRICT, completed_at timestamptz NOT NULL DEFAULT now(), reopened_at timestamptz, reopened_by integer REFERENCES users(id) ON DELETE RESTRICT, reason text);
CREATE UNIQUE INDEX IF NOT EXISTS lms_one_course_completion ON lms_course_completions(student_id,run_id) WHERE reopened_at IS NULL;
CREATE INDEX IF NOT EXISTS lms_material_publications_due ON lms_material_publications(publish_at,enrollment_id) WHERE revoked_at IS NULL;
CREATE INDEX IF NOT EXISTS lms_assignment_student_queue ON lms_assignment_recipients(student_id,status,due_at);
CREATE INDEX IF NOT EXISTS lms_submissions_review_queue ON lms_submissions(submitted_at,recipient_id) WHERE withdrawn_at IS NULL;
CREATE INDEX IF NOT EXISTS lms_quiz_student ON lms_quiz_recipients(student_id,status);
CREATE INDEX IF NOT EXISTS lms_quiz_deadlines ON lms_quiz_attempts(deadline_at) WHERE state='active';
CREATE INDEX IF NOT EXISTS lms_events_student ON lms_learning_events(student_id,id DESC);
CREATE INDEX IF NOT EXISTS lms_threads_queue ON lms_threads(assigned_user_id,status,created_at);
CREATE INDEX IF NOT EXISTS lms_comments_recipient ON lms_comments(recipient_id,id);
CREATE INDEX IF NOT EXISTS lms_reports_student ON lms_reports(student_id,published_at DESC);
ALTER TABLE lms_submissions ADD COLUMN IF NOT EXISTS receipt_snapshot jsonb;
-- Explicit aggregate relations defend direct writes as well as HTTP commands.
CREATE OR REPLACE FUNCTION lms_guard_relations() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_TABLE_NAME='lms_group_runs' THEN
  IF NOT EXISTS(SELECT 1 FROM academy_groups g JOIN lms_course_versions version ON version.course_id=g.course_id WHERE g.id=NEW.group_id AND version.id=NEW.course_version_id) THEN RAISE EXCEPTION 'lms run course mismatch' USING ERRCODE='23514'; END IF;
 ELSIF TG_TABLE_NAME='lms_lesson_bindings' THEN
  IF NOT EXISTS(SELECT 1 FROM lms_group_runs run JOIN academy_lessons lesson ON lesson.group_id=run.group_id WHERE run.id=NEW.run_id AND lesson.id=NEW.lesson_id AND (NEW.unit_id IS NULL OR EXISTS(SELECT 1 FROM lms_units unit WHERE unit.course_version_id=run.course_version_id AND unit.id=NEW.unit_id))) THEN RAISE EXCEPTION 'lms binding mismatch' USING ERRCODE='23514'; END IF;
 ELSIF TG_TABLE_NAME IN('lms_materials','lms_assignments','lms_quizzes','lms_threads') THEN
  IF NEW.unit_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM lms_group_runs run JOIN lms_units unit ON unit.course_version_id=run.course_version_id WHERE run.id=NEW.run_id AND unit.id=NEW.unit_id) THEN RAISE EXCEPTION 'lms unit run mismatch' USING ERRCODE='23514'; END IF;
 ELSIF TG_TABLE_NAME='lms_material_publications' THEN
  IF NOT EXISTS(SELECT 1 FROM lms_materials material JOIN lms_material_versions version ON version.material_id=material.id JOIN lms_group_runs run ON run.id=material.run_id JOIN academy_student_group_enrollments enrollment ON enrollment.group_id=run.group_id WHERE material.id=NEW.material_id AND version.id=NEW.material_version_id AND enrollment.id=NEW.enrollment_id) THEN RAISE EXCEPTION 'lms material audience mismatch' USING ERRCODE='23514'; END IF;
 ELSIF TG_TABLE_NAME='lms_assignment_recipients' THEN
  IF NOT EXISTS(SELECT 1 FROM lms_assignments assignment JOIN lms_assignment_versions version ON version.assignment_id=assignment.id JOIN lms_group_runs run ON run.id=assignment.run_id JOIN academy_student_group_enrollments enrollment ON enrollment.group_id=run.group_id WHERE assignment.id=NEW.assignment_id AND version.id=NEW.assignment_version_id AND enrollment.id=NEW.enrollment_id AND enrollment.student_id=NEW.student_id) THEN RAISE EXCEPTION 'lms assignment audience mismatch' USING ERRCODE='23514'; END IF;
 ELSIF TG_TABLE_NAME='lms_quiz_recipients' THEN
  IF NOT EXISTS(SELECT 1 FROM lms_quizzes quiz JOIN lms_quiz_versions version ON version.quiz_id=quiz.id JOIN lms_group_runs run ON run.id=quiz.run_id JOIN academy_student_group_enrollments enrollment ON enrollment.group_id=run.group_id WHERE quiz.id=NEW.quiz_id AND version.id=NEW.quiz_version_id AND enrollment.id=NEW.enrollment_id AND enrollment.student_id=NEW.student_id) THEN RAISE EXCEPTION 'lms quiz audience mismatch' USING ERRCODE='23514'; END IF;
 ELSIF TG_TABLE_NAME='lms_submissions' THEN
  IF NOT EXISTS(SELECT 1 FROM lms_assignment_recipients recipient WHERE recipient.id=NEW.recipient_id AND recipient.assignment_version_id=NEW.assignment_version_id) THEN RAISE EXCEPTION 'lms submission version mismatch' USING ERRCODE='23514'; END IF;
 ELSIF TG_TABLE_NAME='lms_quiz_attempts' THEN
  IF NOT EXISTS(SELECT 1 FROM lms_quiz_recipients recipient WHERE recipient.id=NEW.recipient_id AND recipient.quiz_version_id=NEW.quiz_version_id) THEN RAISE EXCEPTION 'lms attempt version mismatch' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $$;
DO $$ DECLARE table_name text; BEGIN
 FOREACH table_name IN ARRAY ARRAY['lms_group_runs','lms_lesson_bindings','lms_materials','lms_assignments','lms_quizzes','lms_threads','lms_material_publications','lms_assignment_recipients','lms_quiz_recipients','lms_submissions','lms_quiz_attempts'] LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgname=table_name||'_relations' AND tgrelid=table_name::regclass) THEN EXECUTE format('CREATE TRIGGER %I BEFORE INSERT OR UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION lms_guard_relations()',table_name||'_relations',table_name); END IF;
 END LOOP;
END $$;
CREATE OR REPLACE FUNCTION lms_guard_immutable_history() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'lms immutable history' USING ERRCODE='23514'; END IF;
 IF TG_TABLE_NAME='lms_submissions' THEN
  IF (to_jsonb(OLD)-ARRAY['withdrawn_at','review_started_by','review_started_at','receipt_snapshot']) IS DISTINCT FROM (to_jsonb(NEW)-ARRAY['withdrawn_at','review_started_by','review_started_at','receipt_snapshot']) THEN RAISE EXCEPTION 'lms immutable submission' USING ERRCODE='23514'; END IF;
 ELSE RAISE EXCEPTION 'lms immutable version' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;
DO $$ DECLARE table_name text; BEGIN
 FOREACH table_name IN ARRAY ARRAY['lms_material_versions','lms_assignment_versions','lms_quiz_versions','lms_reviews','lms_submissions'] LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgname=table_name||'_immutable' AND tgrelid=table_name::regclass) THEN EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION lms_guard_immutable_history()',table_name||'_immutable',table_name); END IF;
 END LOOP;
END $$;
CREATE OR REPLACE FUNCTION lms_guard_quiz_attempt_snapshot() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_OP='DELETE' OR OLD.state='finished' OR (to_jsonb(OLD)-ARRAY['answers','version','state','finished_at','score','total_score','percent','passed']) IS DISTINCT FROM (to_jsonb(NEW)-ARRAY['answers','version','state','finished_at','score','total_score','percent','passed']) OR NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'lms immutable quiz snapshot' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgname='lms_quiz_attempt_snapshot' AND tgrelid='lms_quiz_attempts'::regclass) THEN CREATE TRIGGER lms_quiz_attempt_snapshot BEFORE UPDATE OR DELETE ON lms_quiz_attempts FOR EACH ROW EXECUTE FUNCTION lms_guard_quiz_attempt_snapshot(); END IF; END $$;
CREATE TABLE IF NOT EXISTS lms_learning_audit (id bigserial PRIMARY KEY,user_id integer NOT NULL REFERENCES users(id) ON DELETE RESTRICT,run_id bigint REFERENCES lms_group_runs(id) ON DELETE RESTRICT,entity_type text NOT NULL,entity_id bigint NOT NULL,action text NOT NULL,reason text,old_value jsonb,new_value jsonb,request_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS lms_learning_audit_object ON lms_learning_audit(entity_type,entity_id,id DESC);
ALTER TABLE lms_comments ADD COLUMN IF NOT EXISTS audience_account_id integer REFERENCES portal_accounts(id) ON DELETE RESTRICT;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='lms_private_assignment_comment_target' AND conrelid='lms_comments'::regclass) THEN ALTER TABLE lms_comments ADD CONSTRAINT lms_private_assignment_comment_target CHECK(recipient_id IS NULL OR audience<>'representative_teacher' OR audience_account_id IS NOT NULL); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='lms_staff_permission_allowlist' AND conrelid='lms_staff_permissions'::regclass) THEN ALTER TABLE lms_staff_permissions ADD CONSTRAINT lms_staff_permission_allowlist CHECK(permission IN('content.manage','assignments.manage','reviews.manage','quizzes.manage','results.manage','communication.manage','announcements.manage','schedule.manage','access.manage','portfolio.moderate')); END IF; END $$;

ALTER TABLE lms_lesson_bindings ALTER COLUMN unit_id DROP NOT NULL;
ALTER TABLE lms_group_runs ADD COLUMN IF NOT EXISTS version integer NOT NULL DEFAULT 1 CHECK(version>0);

-- Preview metadata is explicitly approved per group and never exposes draft contents.
CREATE TABLE IF NOT EXISTS lms_unit_previews (run_id bigint NOT NULL REFERENCES lms_group_runs(id) ON DELETE RESTRICT, unit_id bigint NOT NULL REFERENCES lms_units(id) ON DELETE RESTRICT, enabled boolean NOT NULL DEFAULT false, visible_from timestamptz NOT NULL, open_at timestamptz NOT NULL, created_by integer NOT NULL REFERENCES users(id) ON DELETE RESTRICT, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(run_id,unit_id), CHECK(open_at>=visible_from));
ALTER TABLE lms_material_versions ADD COLUMN IF NOT EXISTS video_url text CHECK(video_url IS NULL OR video_url ~ '^https://');
ALTER TABLE lms_material_versions ADD COLUMN IF NOT EXISTS duration_minutes integer CHECK(duration_minutes BETWEEN 1 AND 1440);
CREATE INDEX IF NOT EXISTS lms_unit_previews_due ON lms_unit_previews(run_id,visible_from) WHERE enabled;
CREATE OR REPLACE FUNCTION lms_guard_unit_preview() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM lms_group_runs run JOIN lms_units unit ON unit.course_version_id=run.course_version_id WHERE run.id=NEW.run_id AND unit.id=NEW.unit_id) THEN RAISE EXCEPTION 'lms preview unit mismatch' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgname='lms_unit_previews_relation' AND tgrelid='lms_unit_previews'::regclass) THEN CREATE TRIGGER lms_unit_previews_relation BEFORE INSERT OR UPDATE ON lms_unit_previews FOR EACH ROW EXECUTE FUNCTION lms_guard_unit_preview(); END IF; END $$;

ALTER TABLE lms_threads ADD COLUMN IF NOT EXISTS quiz_attempt_id bigint REFERENCES lms_quiz_attempts(id) ON DELETE RESTRICT;
ALTER TABLE lms_threads ADD COLUMN IF NOT EXISTS step_url text CHECK(step_url IS NULL OR step_url ~ '^https://');
CREATE OR REPLACE FUNCTION lms_guard_thread_quiz_context() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.quiz_attempt_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM lms_quiz_attempts attempt JOIN lms_quiz_recipients recipient ON recipient.id=attempt.recipient_id JOIN lms_quizzes quiz ON quiz.id=recipient.quiz_id WHERE attempt.id=NEW.quiz_attempt_id AND recipient.student_id=NEW.student_id AND quiz.run_id=NEW.run_id) THEN RAISE EXCEPTION 'lms thread quiz mismatch' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgname='lms_threads_quiz_relation' AND tgrelid='lms_threads'::regclass) THEN CREATE TRIGGER lms_threads_quiz_relation BEFORE INSERT OR UPDATE ON lms_threads FOR EACH ROW EXECUTE FUNCTION lms_guard_thread_quiz_context(); END IF; END $$;

ALTER TABLE lms_assignments ADD COLUMN IF NOT EXISTS idempotency_key text;
ALTER TABLE lms_assignments ADD COLUMN IF NOT EXISTS request_snapshot jsonb;
ALTER TABLE lms_assignments ADD COLUMN IF NOT EXISTS response_snapshot jsonb;
CREATE UNIQUE INDEX IF NOT EXISTS lms_assignments_author_idempotency ON lms_assignments(created_by,idempotency_key) WHERE idempotency_key IS NOT NULL;

ALTER TABLE lms_reports ADD COLUMN IF NOT EXISTS best_projects jsonb NOT NULL DEFAULT '[]' CHECK(jsonb_typeof(best_projects)='array');
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgname='lms_reports_immutable' AND tgrelid='lms_reports'::regclass) THEN CREATE TRIGGER lms_reports_immutable BEFORE UPDATE OR DELETE ON lms_reports FOR EACH ROW EXECUTE FUNCTION lms_guard_immutable_history(); END IF; END $$;
